// ============================================================
// SCHULUNG: Beispieldaten generieren
// In Produktion wird dieser Node durch echte Datenquelle ersetzt
// ============================================================

const guv_data = [
  { Kostenart: 'Umsatz Inland', Plan: 5200000, Ist: 5450000, Typ: 'Revenue' },
  { Kostenart: 'Umsatz Export', Plan: 3800000, Ist: 3620000, Typ: 'Revenue' },
  { Kostenart: 'Umsatz Gesamt', Plan: 9000000, Ist: 9070000, Typ: 'Revenue' },
  { Kostenart: 'Umsatz Marge %', Plan: 0.42, Ist: 0.41, Typ: 'Percentage' },
  { Kostenart: 'Materialkosten', Plan: 2700000, Ist: 2850000, Typ: 'Cost' },
  { Kostenart: 'Personalkosten', Plan: 3100000, Ist: 3050000, Typ: 'Cost' },
  { Kostenart: 'Sonstige Kosten', Plan: 800000, Ist: 920000, Typ: 'Cost' },
  { Kostenart: 'Kosten Marge %', Plan: 0.73, Ist: 0.75, Typ: 'Percentage' },
  { Kostenart: 'Abschreibungen', Plan: 450000, Ist: 440000, Typ: 'Cost' },
  { Kostenart: 'EBIT', Plan: 1950000, Ist: 1810000, Typ: 'Result' }
];

return guv_data.map(row => ({ json: row }));

// ============================================================
// SCHULUNG: Datentransformation & Bereinigung
// Kernlogik einer Controlling-Pipeline
// ============================================================

const items = $input.all();

// SCHRITT 1: Prozentzeilen ausfiltern
const filtered = items.filter(item => item.json.Typ !== 'Percentage');

// SCHRITT 2: Abweichung berechnen
const enriched = filtered.map(item => {
  const d = item.json;
  let abweichung;

  // WICHTIG: Vorzeichenkonvention!
  // Revenue: Ist > Plan = positiv (gut)
  // Kosten:  Ist > Plan = negativ (schlecht)
  if (d.Typ === 'Revenue' || d.Typ === 'Result') {
    abweichung = d.Ist - d.Plan;
  } else {
    abweichung = -(d.Ist - d.Plan);
  }

  const abweichung_pct = d.Plan !== 0 ? (abweichung / Math.abs(d.Plan)) * 100 : 0;

  let ampel;
  if (abweichung_pct >= 2) ampel = 'gruen';
  else if (abweichung_pct >= -2) ampel = 'gelb';
  else ampel = 'rot';

  return {
    json: {
      ...d,
      Abweichung_EUR: abweichung,
      Abweichung_Pct: Math.round(abweichung_pct * 10) / 10,
      Ampel: ampel
    }
  };
});

return enriched;

// ============================================================
// SCHULUNG: HTML-Report generieren
// Management-tauglicher E-Mail-Report
// ============================================================

const items = $input.all();
const now = new Date();
const dateStr = now.toLocaleDateString('de-DE', { day: '2-digit', month: '2-digit', year: 'numeric' });

const ampelColor = { 'gruen': '#27ae60', 'gelb': '#f39c12', 'rot': '#e74c3c' };

function fmtEUR(val) {
  return new Intl.NumberFormat('de-DE', { maximumFractionDigits: 0 }).format(val);
}
function fmtPct(val) {
  return val.toFixed(1).replace('.', ',');
}

let tableRows = '';
for (const item of items) {
  const d = item.json;
  const color = ampelColor[d.Ampel] || '#95a5a6';
  const sign = d.Abweichung_EUR >= 0 ? '+' : '';
  tableRows += `<tr>
    <td style="padding:8px 12px;border-bottom:1px solid #eee;font-weight:${d.Typ==='Result'?'bold':'normal'}">${d.Kostenart}</td>
    <td style="padding:8px 12px;border-bottom:1px solid #eee;text-align:right">${fmtEUR(d.Plan)}</td>
    <td style="padding:8px 12px;border-bottom:1px solid #eee;text-align:right">${fmtEUR(d.Ist)}</td>
    <td style="padding:8px 12px;border-bottom:1px solid #eee;text-align:right;color:${d.Abweichung_EUR>=0?'#27ae60':'#e74c3c'}">${sign}${fmtEUR(d.Abweichung_EUR)}</td>
    <td style="padding:8px 12px;border-bottom:1px solid #eee;text-align:right">${sign}${fmtPct(d.Abweichung_Pct)} %</td>
    <td style="padding:8px 12px;border-bottom:1px solid #eee;text-align:center"><span style="display:inline-block;width:16px;height:16px;border-radius:50%;background:${color}"></span></td>
  </tr>`;
}

const ebit = items.find(i => i.json.Kostenart === 'EBIT');
const ebitAbw = ebit ? ebit.json.Abweichung_EUR : 0;
const ebitAmpel = ebit ? ebit.json.Ampel : 'gelb';

const html = `<!DOCTYPE html><html><head><meta charset="utf-8"></head>
<body style="font-family:'Segoe UI',Arial,sans-serif;color:#2c3e50;max-width:800px;margin:0 auto;padding:20px;">
  <div style="background:linear-gradient(135deg,#2c3e50,#3498db);color:white;padding:24px 32px;border-radius:8px 8px 0 0;">
    <h1 style="margin:0;font-size:22px;">Monatlicher Controlling-Report</h1>
    <p style="margin:4px 0 0 0;opacity:0.85;font-size:14px;">Automatisch erstellt am ${dateStr} | Unternehmen A</p>
  </div>
  <div style="background:#f8f9fa;padding:20px 32px;border-left:1px solid #e0e0e0;border-right:1px solid #e0e0e0;">
    <h2 style="font-size:16px;margin:0 0 12px 0;">Executive Summary</h2>
    <ul style="margin:0;padding-left:20px;line-height:1.8;">
      <li>Umsatz leicht ueber Plan (+0,8%) — Inland kompensiert Exportrueckgang</li>
      <li>Materialkosten ueber Budget (+150 kEUR) — Preiseffekt Halbleiter</li>
      <li>Personalkosten unter Plan (-50 kEUR) — offene Stelle BU Engineering</li>
      <li><strong>EBIT ${fmtEUR(Math.abs(ebitAbw))} EUR ${ebitAbw>=0?'ueber':'unter'} Plan</strong> — Ampel: <span style="color:${ampelColor[ebitAmpel]};font-weight:bold;">${ebitAmpel.toUpperCase()}</span></li>
      <li>Handlungsbedarf: Materialkostenentwicklung im naechsten RF adressieren</li>
    </ul>
  </div>
  <div style="padding:20px 32px;border:1px solid #e0e0e0;border-top:none;">
    <h2 style="font-size:16px;margin:0 0 12px 0;">Plan-Ist-Vergleich (kumuliert YTD)</h2>
    <table style="width:100%;border-collapse:collapse;font-size:14px;">
      <thead><tr style="background:#2c3e50;color:white;">
        <th style="padding:10px 12px;text-align:left;">Position</th>
        <th style="padding:10px 12px;text-align:right;">Plan (EUR)</th>
        <th style="padding:10px 12px;text-align:right;">Ist (EUR)</th>
        <th style="padding:10px 12px;text-align:right;">Abw. (EUR)</th>
        <th style="padding:10px 12px;text-align:right;">Abw. (%)</th>
        <th style="padding:10px 12px;text-align:center;">Status</th>
      </tr></thead>
      <tbody>${tableRows}</tbody>
    </table>
  </div>
  <div style="background:#f8f9fa;padding:16px 32px;border:1px solid #e0e0e0;border-top:none;border-radius:0 0 8px 8px;font-size:12px;color:#7f8c8d;">
    <p style="margin:0;">Automatisch generiert via n8n | Datenquelle: D365 (simuliert) | Schulungsbeispiel</p>
  </div>
</body></html>`;

return [{ json: { html_report: html, subject: `Controlling-Report ${dateStr} | Unternehmen A`, date: dateStr } }];
